'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { performance } = require('node:perf_hooks');
const { evaluate, ExprError } = require('./src');

function errorAt(source, column, variables) {
  assert.throws(() => evaluate(source, variables), error => {
    assert.ok(error instanceof ExprError);
    assert.equal(error.column, column, source);
    return true;
  });
}

test('arithmetic precedence, associativity, literals and calls', () => {
  const cases = [
    ['-2 ** 2', -4], ['(-2) ** 2', 4], ['2 ** -1', 0.5],
    ['2 ** 3 ** 2', 512], ['2 ** -2 ** 2', 0.0625],
    ['-2 ** -2', -0.25], ['--2 ** 2', 4], ['2 * -3 ** 2', -18],
    ['8 / 2 * 3', 12], ['10 - 3 - 2', 5], ['20 // 3 % 4', 2],
    ['.5 + 5. + 1.5e-3 + 2E+1', 25.5015],
    ['min(3, max(1, 2), abs(-4))', 2], ['max(-5)', -5],
    ['abs(2 > 1)', 1], ['min(2, 3 < 1)', 0],
  ];
  for (const [source, expected] of cases) assert.equal(evaluate(source), expected, source);
});

test('signed division and remainder, including positive zero and booleans', () => {
  for (let a = -10; a <= 10; a++) {
    for (let b = -5; b <= 5; b++) {
      if (b === 0) continue;
      const q = evaluate('a // b', { a, b });
      const r = evaluate('a % b', { a, b });
      const expected = Math.floor(a / b);
      assert.equal(q, expected === 0 ? 0 : expected);
      assert.equal(a, q * b + r);
      assert.ok(r === 0 || (r < 0) === (b < 0));
      if (q === 0) assert.ok(!Object.is(q, -0));
      if (r === 0) assert.ok(!Object.is(r, -0));
    }
  }
  assert.equal(evaluate('-5.5 % 2'), 0.5);
  assert.equal(evaluate('5.5 % -2'), -0.5);
  assert.equal(evaluate('(1 < 2) + (2 < 1)'), 1);
  assert.equal(evaluate('(1 < 2) == 1'), true);
  assert.equal(evaluate('1 / (1 < 2)'), 1);
  for (const operator of ['/', '//', '%']) {
    const source = `  1   ${operator}  -0`;
    errorAt(source, source.indexOf(operator) + 1);
    const booleanSource = `1 ${operator} (2 < 1)`;
    errorAt(booleanSource, 3);
  }
});

test('comparisons chain and short-circuit with numeric boolean coercion', () => {
  const cases = [
    ['3 < 2 < missing', false], ['3 < 2 < (1 / 0)', false],
    ['1 < 2 <= 2 != 3 == 3', true], ['1 < 2 > 3', false],
    ['3 > 2 >= 2', true], ['2 == 2 != 2', false],
    ['(3 < 2) < 1', true], ['1 < (3 < 2)', false],
    ['1 + 2 * 3 == 7', true],
  ];
  for (const [source, expected] of cases) assert.equal(evaluate(source), expected, source);
  errorAt('1 < 2 < missing', 9);
});

test('getters run once per occurrence in left-to-right order; only own properties', () => {
  const trace = [];
  const variables = {};
  for (const [name, value] of [['a', 1], ['b', 2], ['c', 3], ['d', 4]]) {
    Object.defineProperty(variables, name, { get() { trace.push(name); return value; } });
  }
  Object.freeze(variables);
  assert.equal(evaluate('a < b <= c < d', variables), true);
  assert.deepEqual(trace.splice(0), ['a', 'b', 'c', 'd']);
  assert.equal(evaluate('c < b < a', variables), false);
  assert.deepEqual(trace.splice(0), ['c', 'b']);
  assert.equal(evaluate('max(a + b, c * d, a ** b)', variables), 12);
  assert.deepEqual(trace.splice(0), ['a', 'b', 'c', 'd', 'a', 'b']);
  errorAt('  inherited', 3, Object.create({ inherited: 7 }));
  errorAt('toString', 1, {});
  assert.equal(evaluate('own', Object.assign(Object.create(null), { own: 7 })), 7);
});

test('syntax and character errors retain token and EOF UTF-16 columns', () => {
  const cases = [
    ['1 +   missing', 7], ['  @', 3], ['1 + \t😀', 6],
    ['1 +   ', 7], ['   ', 4], ['', 1], ['(1   ', 6],
    ['1   2', 5], ['2(3)', 2], ['1 = 2', 3], ['1 ! 2', 3],
    ['1 +   )', 7], ['min(1,)', 7], ['abs(1 2)', 7],
    ['  unknown(1)', 3], ['  abs()', 3], ['  abs(1, 2)', 3],
    ['  min()', 3], ['  max()', 3], ['1 < 0 <   abs()', 11],
  ];
  for (const [source, column] of cases) errorAt(source, column);
  let reads = 0;
  const variables = { get a() { reads++; return 1; } };
  for (const source of ['a + unknown(1)', 'a + abs(1, 2)', 'a < 0 < abs()', 'a +   ']) {
    assert.throws(() => evaluate(source, variables), ExprError);
    assert.equal(reads, 0);
  }
});

test('100,001-operand flat arithmetic and comparison chains stay linear and stack-safe', () => {
  const count = 100001;
  let reads = 0;
  const variables = { get next() { return reads++; } };
  const arithmetic = Array(count).fill('1').join('+');
  const comparisons = Array(count).fill('next').join('<');
  let start = performance.now();
  assert.equal(evaluate(arithmetic), count);
  const arithmeticMs = performance.now() - start;
  start = performance.now();
  assert.equal(evaluate(comparisons, variables), true);
  const comparisonMs = performance.now() - start;
  assert.equal(reads, count);
  console.log(`100,001 operands: arithmetic ${arithmeticMs.toFixed(1)} ms; comparisons ${comparisonMs.toFixed(1)} ms`);
  assert.ok(arithmeticMs < 1000, `arithmetic took ${arithmeticMs} ms`);
  assert.ok(comparisonMs < 1000, `comparisons took ${comparisonMs} ms`);
});

