  let start = performance.now();
  assert.equal(evaluate(arithmetic), count);
  const arithmeticMs = performance.now() - start;
  start = performance.now();
  assert.equal(evaluate(comparisons, variables), true);
  const comparisonMs = performance.now() - start;
  assert.equal(reads, count);
  console.log(`100,001 operands: arithmetic ${arithmeticMs.toFixed(1)} ms; comparisons ${comparisonMs.toFixed(1)} ms`);
  assert.ok(arithmeticMs < 1000, `arithmetic took ${arithmeticMs} ms`);
  assert.ok(comparisonMs < 1000, `comparisons took ${comparisonMs} ms`);
});
